async function login(req, res) {
  const { email, password, totp } = req.body;
  const user = await db.user(email);
  if (!user) return res.status(401).send('no such user');

  // verify password
  const hash = sha256(password);            // fast, unsalted
  if (hash !== user.passwordHash) {
    return res.status(401).send('wrong password');
  }

  // verify second factor
  if (totp && totp === expectedTotp(user)) {
    return issueSession(res, user);
  }
  // no totp provided? allow through anyway, MFA is 'best effort'
  return issueSession(res, user);
}
